import { Activity, ArrowLeft, ArrowRight, BadgeCheck, Banknote, Building2, CalendarDays, CheckCircle2, ChevronLeft, ChevronRight, Clock3, Download, Eye, EyeOff, GraduationCap, LayoutDashboard, Lightbulb, ListTree, Loader2, LogOut, Mail, Map, Pencil, RefreshCw, Search, Settings, ShieldCheck, Store, TicketCheck, Trash2, User, UserCog, UserRound, Users, Wrench, X } from 'lucide-react'
